/**
 * Jinx Alchemist + Mastermind: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Alchemist
 * Wiki: https://wiki.bloodontheclocktower.com/Mastermind
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/abilities/ability.ts';
import { hasAbilityOf } from '#lib/core/rules/abilities/gained-abilities.ts';
import { gameEnds } from '#lib/core/rules/game-end/game-end.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes/jinx-pairs.ts';
import { alchemistAs, bagNotes } from './alchemist.test-support.ts';

describe('Alchemist + Mastermind jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alchemist', 'mastermind');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alchemist')?.name).toBe('Alchemist');
		expect(data.byId.get('mastermind')?.name).toBe('Mastermind');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alchemist', 'mastermind'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alchemist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['mastermind'])).not.toContain(jinx);
	});

	describe('an Alchemist-Mastermind has no Mastermind ability', () => {
		const base = alchemistAs('mastermind', ['chef', 'empath', 'imp', 'monk']);

		it("is data in the Alchemist's rules", () => {
			// Wiki: "An Alchemist-Mastermind has no Mastermind ability & the Mastermind is not-in-play."
			expect(jinxRulesBetween('alchemist', 'mastermind', committedCharacters())).toEqual({
				impairs: { kind: 'no-ability', when: ['has-partner-ability'] }
			});
		});

		it('notes it at setup when the Alchemist is chosen', () => {
			// Wiki: "An Alchemist-Mastermind has no Mastermind ability"
			const note = 'Alchemist with the Mastermind ability: the Alchemist has no ability.';
			expect(bagNotes('mastermind')).toContain(note);
			expect(bagNotes('mastermind', false)).not.toContain(note);
		});

		it('leaves the Alchemist-Mastermind with no ability', () => {
			// Wiki: "An Alchemist-Mastermind has no Mastermind ability"
			const state = abilityState(base.game, base.seat(0), base.characters);
			expect(state.impairments).toMatchObject([
				{ reason: 'no-ability', source: { characterId: 'mastermind' } }
			]);
			expect(hasAbilityOf(base.game, base.seat(0), 'mastermind', base.characters)).toBe(false);
		});

		it("doesn't give an extra day when the Demon is executed", () => {
			// Wiki: "An Alchemist-Mastermind has no Mastermind ability & the Mastermind is not-in-play."
			const s = base.execute('imp');
			const end = gameEnds(s.game, s.characters).find((e) => e.rule === 'demon-dead');
			expect(end?.holds.filter((h) => h.rule === 'extra-day')).toEqual([]);
		});
	});
});
